import {playRaidScene,cancelRaidScene} from './raid-scenes.mjs';
import {buildRaid,fillBotActions,settleRaid} from './raid-model.mjs';
import {migrate} from './model.mjs';

export function startRaid(){const g=this.g;if(this.active)return;if(!g.state.roster.length)return g.toast('Choisis d’abord ton starter.');if(g.net.guest){g.net.sendReady();return g.toast('Partenaire prêt. L’hôte peut lancer le raid.')}if(g.net.connections.size!==g.net.players.length)return g.toast('Attends que les alliés connectés aient choisi leur partenaire.');this.botTakeovers=new Set();const b=buildRaid(g);this.mount(b);g.net.broadcast({type:'battle-start',battle:b})}
export function prepareRaidTurn(){if(!this.data?.raid||this.g.net.guest)return;for(const pid of this.botTakeovers||[])for(const b of [this.data,this.visual]){const t=b.teams.find(t=>t.pid===pid);if(t){t.bot=true;t.name=t.name.replace(/ · Bot$/,'')+' · Bot'}}fillBotActions(this.data,this.g.chart)}
export async function finishRaid(){const b=this.data,g=this.g,session=this.session;if(this.finishing===b.id)return;this.finishing=b.id;cancelRaidScene(this);g.audio.music.setScene(b.win?'victory':'defeat');let reward;
 const claim=()=>{let saved;try{saved=JSON.parse(localStorage.getItem('tour-infernale-v1'))}catch{}const state=saved?migrate(saved):g.state;reward=settleRaid(state,b,g.net.myId,g.dex);g.state=state;g.save()};if(navigator.locks)await navigator.locks.request('pokeworld-combat-reward',claim);else claim();
 if(!this.active||session!==this.session)return;
 if(!g.net.guest){g.net.encounter=b.nextEncounter;g.net.syncLobby?.()}
 if(reward?.shiny){await playRaidScene(this,'capture',{key:reward.key});if(!this.active||session!==this.session)return;g.audio.chime('legendary');if(reward.pokemon?.story){try{await g.cinema.play(reward.pokemon)}finally{g.closeModal(true)}}}
 if(!this.active||session!==this.session)return;
 const root=g.modeRoot,end=root.querySelector('.battle-end');end.hidden=false;root.querySelector('#battle-end-label').textContent=b.win?'RAID TERMINÉ · RÉSULTAT PERSONNEL':'RAID TERMINÉ';root.querySelector('#battle-end-title').textContent=reward?.expelled?'La faille t’a expulsé':b.raidOutcome==='timeout'?'La faille s’est refermée':reward?.shiny?'✧ '+g.poke(reward.key).name+' chromatique !':b.win?'Boss vaincu !':'Le raid est perdu';root.querySelector('#battle-end-reward').textContent=reward?.expelled?'Ton partenaire a été mis K.O. Tes alliés ont pu poursuivre, mais tu ne peux pas capturer sur ce raid.':b.raidOutcome==='timeout'?'Le boss n’a pas été vaincu en 20 tours. Le groupe est expulsé, sans tirage chromatique.':reward?.shiny?(reward.pokemon.duplicate?'Un nouvel exemplaire chromatique rejoint ta collection. Les meilleurs IV sont conservés.':'Ce Pokémon chromatique rejoint ta collection !'):b.win?'Le boss n’est pas chromatique pour toi. Aucun Pokémon obtenu cette fois. Chaque victoire donne 5 % de chance, indépendamment de tes alliés.':'Aucun tirage chromatique en cas de défaite. Un nouveau boss vous attend.';root.querySelector('[data-act="finish-battle"]').textContent='Retour à l’Antre →';
 if(reward?.shiny){const c=document.createElement('canvas');c.width=220;c.height=150;c.dataset.raidReward=reward.key;c.setAttribute('aria-label',g.poke(reward.key).name+' chromatique obtenu');end.insertBefore(c,root.querySelector('#battle-end-title'))}
}
